head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > displayFormatFunc]<br/>Calendar 컴포넌트 하단에 표시되는 선택일 포맷을 사용자 정의 함수를 통해 설정합니다.",
    "validation" : [
        "Calendar 컴포넌트 하단에 표시되는 선택일 포맷을 사용자 정의 함수를 통해 설정합니다.",
        "표시되는 선택일 포맷 문자열을 반환하는 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 파라미터로 calendarValueType 속성값이 전달됩니다.",
        "사용자 정의 함수의 반환값이 표시되는 선택일의 새로운 포맷으로 적용됩니다.",
        "사용자 정의 함수의 반환값이 없거나 ''(Empty String)이면 calendarValueType 속성값에 맞는 기본값이 적용됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        displayFormatFunc : con_displayFormatFunc.getText(),
        // 하단 currentDate 영역이 표시되는 모드 (yearMonthDate, yearMonthDateHour 만 하단 표시됨)
        calendarValueType : con_calendarValueType.getText()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // 초기 선택일 설정 (calendarValueType 별 자릿수 맞춤)
    let cvt = target1.options.calendarValueType;
    let initVal = ({
        'yearMonthDate'       : '20250518',
        'yearMonthDateHour'   : '2025051812',
        'yearMonthDateTime'   : '202505181234',
        'yearMonthDateTimeSec': '20250518123456'
    })[cvt] || '20250518';
    // createBasicCalendar 내부 비동기 작업 완료 후 setValue 호출되도록 지연
    setTimeout(() =&gt; { target1.setValue(initVal); }, 100);
}



// 사용자 정의 함수 - 고정 포맷 반환
scwin.fn_returnFixedFormat = function (valueType) {
    // validation: 반환값이 표시되는 선택일의 새로운 포맷으로 적용됨
    return "yyyy-MM-dd";
};



// 사용자 정의 함수 - calendarValueType 별 다른 포맷 반환 (마스크 문자 yyyy/MM/dd/EEE/HH/mm/SS 적용)
scwin.fn_returnByValueType = function (valueType) {
    // validation: 파라미터로 calendarValueType 속성값이 전달되어 분기됨 + 마스크 문자 적용
    let dp_format = "yyyy-MM-dd";

    switch (valueType) {
        case "yearMonthDate" :
            dp_format = "yyyy/MM/dd(EEE)";
            break;
        case "yearMonthDateHour" :
            dp_format = "yyyy/MM/dd HH시";
            break;
        case "yearMonthDateTime" :
            dp_format = "yyyy/MM/dd HH:mm";
            break;
        case "yearMonthDateTimeSec" :
            dp_format = "yyyy/MM/dd HH:mm:SS";
            break;
    }

    return dp_format;
};



// 사용자 정의 함수 - 빈 문자열 반환
scwin.fn_returnEmpty = function (valueType) {
    // @spec validation: 반환값이 ''(Empty String)이면 calendarValueType 속성값에 맞는 기본값 적용
    return "";
};



scwin.btn_getDisplayedText_onclick = function (e) {
    // calendar 내부 currentDate 영역
    const element = target1.render.querySelector('[id$="_currentDate"]')
                 || target1.render.querySelector('[class*="currentDate"]');

    let displayed = element ? element.textContent : '(currentDate 없음)';
    // validation: 함수 반환값 적용 / calendarValueType 별 분기 / 빈 반환값 시 기본 포맷 적용
    wf_body_bottom.getObj("scwin").setReturnValue("[하단 선택일 표시] '" + displayed + "'");
};
